#!/usr/bin/env python3
"""PT-fuse the scoped proto from bssn_manually_staged.rhs_with_d_computations()."""
from __future__ import annotations

import re
from pathlib import Path

HERE = Path(__file__).resolve().parent

HEADER = """\
// Auto-generated by gen_gauge6_pt_scoped.py — section-scoped PT_ASYNC.
#ifndef PT_FUSED_X3
#define PT_FUSED_X3 device::__pt_fused_x3
#define PT_FUSED_Y3 device::__pt_fused_y3
#define PT_FUSED_Z3 device::__pt_fused_z3
#endif
const DEVICE_REAL inv_dx = 1.0 / blk->m_dx[0];
const DEVICE_REAL inv_dy = 1.0 / blk->m_dx[1];
const DEVICE_REAL inv_dz = 1.0 / blk->m_dx[2];
"""


def pt_full(var: str) -> str:
    return f"""device::__ld_blk_var1_async_issue__<nx>(su, {var});
device::__ld_blk_var1_async_wait__();
DEVICE_REAL grad_0_{var}, grad2_0_0_{var}, kograd_0_{var};
DEVICE_REAL grad_1_{var}, grad2_1_1_{var}, kograd_1_{var};
DEVICE_REAL grad_2_{var}, grad2_2_2_{var}, kograd_2_{var};
PT_FUSED_X3<nx>(su, i, j, k, inv_dx, &grad_0_{var}, &grad2_0_0_{var}, &kograd_0_{var});
PT_FUSED_Y3<nx>(su, i, j, k, inv_dy, &grad_1_{var}, &grad2_1_1_{var}, &kograd_1_{var});
PT_FUSED_Z3<nx>(su, i, j, k, inv_dz, &grad_2_{var}, &grad2_2_2_{var}, &kograd_2_{var});
const DEVICE_REAL grad2_0_1_{var} = device::__pt_dxy<nx>(su, i, j, k, inv_dx, inv_dy);
const DEVICE_REAL grad2_0_2_{var} = device::__pt_dxz<nx>(su, i, j, k, inv_dx, inv_dz);
const DEVICE_REAL grad2_1_2_{var} = device::__pt_dyz<nx>(su, i, j, k, inv_dy, inv_dz);
__syncthreads();
"""


def pt_first_ko(var: str, with_ko: bool = True) -> str:
    ko_decl = f", kograd_0_{var}" if with_ko else ""
    ko_decl2 = f", kograd_1_{var}" if with_ko else ""
    ko_decl3 = f", kograd_2_{var}" if with_ko else ""
    ko_ptr = f"&kograd_0_{var}" if with_ko else "nullptr"
    ko_ptr2 = f"&kograd_1_{var}" if with_ko else "nullptr"
    ko_ptr3 = f"&kograd_2_{var}" if with_ko else "nullptr"
    # Always declare kograd if with_ko; if not, still need grad only
    if with_ko:
        decls = f"""DEVICE_REAL grad_0_{var}, kograd_0_{var};
DEVICE_REAL grad_1_{var}, kograd_1_{var};
DEVICE_REAL grad_2_{var}, kograd_2_{var};"""
    else:
        decls = f"""DEVICE_REAL grad_0_{var};
DEVICE_REAL grad_1_{var};
DEVICE_REAL grad_2_{var};"""
    return f"""device::__ld_blk_var1_async_issue__<nx>(su, {var});
device::__ld_blk_var1_async_wait__();
{decls}
PT_FUSED_X3<nx>(su, i, j, k, inv_dx, &grad_0_{var}, nullptr, {ko_ptr});
PT_FUSED_Y3<nx>(su, i, j, k, inv_dy, &grad_1_{var}, nullptr, {ko_ptr2});
PT_FUSED_Z3<nx>(su, i, j, k, inv_dz, &grad_2_{var}, nullptr, {ko_ptr3});
__syncthreads();
"""


BLK1_VAR = re.compile(
    r"device::__ld_blk_var1__<DEVICE_REAL,pw,nx>\s*\(su\s*,\s*(\w+)\s*,\s*blk\);\n"
    r"(?:device::__blk1_[^\n]+\n__syncthreads\(\);\n"
    r"const DEVICE_REAL (?:grad2_|grad_|kograd_)[^\n]+\n__syncthreads\(\);\n)+",
    re.MULTILINE,
)


def replace_blk1_with_pt(text: str) -> str:
    def repl(m: re.Match) -> str:
        var = m.group(1)
        body = m.group(0)
        if f"grad2_0_0_{var}" in body:
            return pt_full(var)
        with_ko = f"kograd_0_{var}" in body
        return pt_first_ko(var, with_ko=with_ko)

    new, n = BLK1_VAR.subn(repl, text)
    print(f"replaced {n} blk1 blocks")
    leftover = new.count("__blk1_")
    if leftover:
        print(f"WARNING: {leftover} blk1 refs remain")
    return new


def main() -> None:
    proto = HERE / "gauge6_point_async_staged_proto.cpp"
    raw = proto.read_text()
    raw = re.sub(r"^// Auto-generated.*\n", "", raw)
    raw = replace_blk1_with_pt(raw)
    # Drop pencils/Du/DDu leftovers if any
    raw = raw.replace("pencils,pencil_sz", "/*pt*/")
    dst = HERE / "gauge6_point_async_scoped.cpp"
    dst.write_text(HEADER + raw)
    print(f"wrote {dst} ({dst.stat().st_size} bytes)")


if __name__ == "__main__":
    main()
